        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(ISceneGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (FormLinkInformation.TryFactory(obj.ParentQuest, out var ParentQuestInfo))
            {
                yield return ParentQuestInfo;
            }
            if (obj.Keywords is {} KeywordsItem)
            {
                foreach (var item in KeywordsItem)
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.TemplateScene, out var TemplateSceneInfo))
            {
                yield return TemplateSceneInfo;
            }
            if (FormLinkInformation.TryFactory(obj.AudioOutputOverride, out var AudioOutputOverrideInfo))
            {
                yield return AudioOutputOverrideInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ALID, out var ALIDInfo))
            {
                yield return ALIDInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ATTR, out var ATTRInfo))
            {
                yield return ATTRInfo;
            }
            if (FormLinkInformation.TryFactory(obj.DATA, out var DATAInfo))
            {
                yield return DATAInfo;
            }
            if (FormLinkInformation.TryFactory(obj.DNAM, out var DNAMInfo))
            {
                yield return DNAMInfo;
            }
            if (FormLinkInformation.TryFactory(obj.DTGT, out var DTGTInfo))
            {
                yield return DTGTInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ENAM, out var ENAMInfo))
            {
                yield return ENAMInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ESCE, out var ESCEInfo))
            {
                yield return ESCEInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ESCS, out var ESCSInfo))
            {
                yield return ESCSInfo;
            }
            if (FormLinkInformation.TryFactory(obj.HTID, out var HTIDInfo))
            {
                yield return HTIDInfo;
            }
            if (FormLinkInformation.TryFactory(obj.LCEP, out var LCEPInfo))
            {
                yield return LCEPInfo;
            }
            if (FormLinkInformation.TryFactory(obj.LNAM, out var LNAMInfo))
            {
                yield return LNAMInfo;
            }
            if (FormLinkInformation.TryFactory(obj.WNAM, out var WNAMInfo))
            {
                yield return WNAMInfo;
            }
            if (obj.Conditions is {} ConditionsItem)
            {
                foreach (var item in ConditionsItem.WhereCastable<IConditionGetter, IFormLinkContainerGetter>()
                    .SelectMany((f) => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            yield break;
        }
        
