        public Scene Duplicate(
            ISceneGetter item,
            FormKey formKey,
            TranslationCrystal? copyMask)
        {
            var newRec = new Scene(formKey, item.FormVersion);
            newRec.DeepCopyIn(item, default(ErrorMaskBuilder?), copyMask);
            return newRec;
        }
        
